import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

public class Main {
    static class Siswa {
        String nama;
        int nilai;

        Siswa(String nama, int nilai) {
            this.nama = nama;
            this.nilai = nilai;
        }

        @Override
        public String toString() {
            return nama + "(" + nilai + ")";
        }
    }

    public static void main(String[] args) {
        List<Siswa> daftar = new ArrayList<Siswa>();
        daftar.add(new Siswa("Budi", 80));
        daftar.add(new Siswa("Ani", 95));
        daftar.add(new Siswa("Citra", 70));

        Collections.sort(daftar, new Comparator<Siswa>() {
            public int compare(Siswa a, Siswa b) {
                return a.nilai - b.nilai;
            }
        });
        System.out.println(daftar);

        Collections.sort(daftar, new Comparator<Siswa>() {
            public int compare(Siswa a, Siswa b) {
                return a.nama.compareTo(b.nama);
            }
        });
        System.out.println(daftar);
    }
}

