import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

public class Main {
    static class Produk {
        String nama;
        int harga;

        Produk(String nama, int harga) {
            this.nama = nama;
            this.harga = harga;
        }

        @Override
        public String toString() {
            return nama + "=" + harga;
        }
    }

    public static void main(String[] args) {
        List<Produk> daftar = new ArrayList<Produk>();
        daftar.add(new Produk("Kopi", 25000));
        daftar.add(new Produk("Teh", 15000));
        daftar.add(new Produk("Susu", 30000));
        Collections.sort(daftar, new Comparator<Produk>() {
            public int compare(Produk a, Produk b) {
                return b.harga - a.harga;
            }
        });
        System.out.println(daftar);
    }
}

